/**
 * The HTTP security and caching headers the deployed site must send.
 *
 * One definition feeds three places so they cannot drift apart: the local production-like server (serve.mjs, used by
 * the browser tests), the deployment configuration (vercel.json, generated by write-deploy-config.mjs), and a
 * check in the test suite that the committed vercel.json still matches.
 */

/**
 * Content-Security-Policy. The site loads nothing from other websites, so almost everything is 'self'.
 *  - script-src 'wasm-unsafe-eval': the documentation search (Pagefind) runs a small WebAssembly module.
 *  - style-src 'unsafe-inline': a few elements carry style attributes. Scripts stay strict: no inline code.
 *  - connect-src: this site plus the API the forms post to (the only other place the browser may talk to).
 *  - frame-ancestors 'none': nobody may embed this site in a frame (clickjacking).
 */
export function contentSecurityPolicy({ apiOrigin } = {}) {
  const connect = ["'self'", ...(apiOrigin ? [apiOrigin] : [])].join(" ");
  return [
    "default-src 'self'",
    "script-src 'self' 'wasm-unsafe-eval'",
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data:",
    "font-src 'self'",
    `connect-src ${connect}`,
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
    "upgrade-insecure-requests",
  ].join("; ");
}

/** Headers for every response. */
export function securityHeaders(options = {}) {
  return {
    "Content-Security-Policy": contentSecurityPolicy(options),
    // One year; add "preload" only once the final domain is chosen and HTTPS is permanent.
    "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=(), payment=(), interest-cohort=()",
    "Cross-Origin-Opener-Policy": "same-origin",
    "X-Frame-Options": "DENY",
  };
}

/** Caching: fingerprinted assets never change, so they can be cached for a year; pages must be revalidated. */
export function cacheControlFor(pathname) {
  if (pathname.startsWith("/_astro/") || pathname.startsWith("/pagefind/")) return "public, max-age=31536000, immutable";
  if (/\.(?:png|webp|woff2|ico)$/.test(pathname)) return "public, max-age=86400";
  return "public, max-age=0, must-revalidate";
}

/** The deployment configuration for Vercel, derived from the definitions above. */
export function vercelConfig(options = {}) {
  const toList = (headers) => Object.entries(headers).map(([key, value]) => ({ key, value }));
  // How Vercel builds the site. The website needs the widget built first (it ships a copy), and npm workspaces
  // install from the repository root, so the commands differ by where the Vercel project's Root Directory points.
  const build = {
    // Root Directory left at the repository root (the default).
    repo: { installCommand: "npm ci", buildCommand: "npm run build -w @eagles-eye/widget && npm run build -w @eagles-eye/website", outputDirectory: "apps/website/dist" },
    // Root Directory set to apps/website.
    site: { installCommand: "cd ../.. && npm ci", buildCommand: "cd ../.. && npm run build -w @eagles-eye/widget && npm run build -w @eagles-eye/website", outputDirectory: "dist" },
  }[options.build ?? "site"];
  return {
    $schema: "https://openapi.vercel.sh/vercel.json",
    framework: null,
    ...build,
    cleanUrls: false,
    trailingSlash: true,
    headers: [
      { source: "/(.*)", headers: toList(securityHeaders(options)) },
      { source: "/_astro/(.*)", headers: [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }] },
      { source: "/pagefind/(.*)", headers: [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }] },
    ],
  };
}
